import fs from 'node:fs';import {fixtures,poem,nursery,registry} from './data.mjs';
import {esc,icon,link,btn,details,blockDetails,block,workPage,verseCard,copyBtn,shareBlock,workUrl,gk,notice,empty,section,bread,verse,level,meaning,flag,card,actions,materials,contribute,footerOfWork,gameParams,gameSteps,collectionItem} from './common.mjs';
export const extraViews={};const V=extraViews;
const input=(id,label,value='',type='text')=>`<label for="${id}">${label}</label><input id="${id}" name="${id}" type="${type}" value="${esc(value)}">`;
const area=(id,label,value='')=>`<label for="${id}">${label}</label><textarea id="${id}" name="${id}">${esc(value)}</textarea>`;
const select=(id,label,values)=>`<label for="${id}">${label}</label><select id="${id}" name="${id}">${values.map((v,i)=>`<option value="${i}">${v}</option>`).join('')}</select>`;
const alpha=()=>`<div class="alpha" aria-label="Chữ cái tiếng Việt">${'A Ă Â B C D Đ E Ê G H I K L M N O Ô Ơ P Q R S T U Ư V X Y'.split(' ').map(x=>`<button data-action="alphabet" aria-pressed="false">${x}</button>`).join('')}</div><p id="alphabet-status" class="small muted" aria-live="polite"></p>`;
const filterControls=()=>`<details class="filters" open><summary>Bộ lọc <span id="filter-count" class="count">· chưa chọn</span></summary><form id="catalog-filters"><div class="field-grid"><div><label for="filter-genre">Thể loại</label><select id="filter-genre"><option value="">Tất cả</option><option>Ca dao</option><option>Tục ngữ – Thành ngữ</option><option>Đồng dao</option><option>Vè</option><option>Câu đố</option></select></div><div><label for="filter-topic">Chủ đề</label><select id="filter-topic"><option value="">Tất cả chủ đề</option><option>Lao động</option><option>Học tập</option></select></div><div><label for="filter-form">Hình thức</label><select id="filter-form"><option value="">Tất cả hình thức</option><option>Lục bát</option><option>Văn xuôi</option></select></div><div><label for="filter-region">Nơi lưu truyền</label><select id="filter-region"><option value="">Chưa giới hạn</option><option value="unknown">Chưa ghi nhận</option><option value="sample">Vùng mẫu có căn cứ</option></select></div></div><div class="actions">${btn('apply-filters','Áp dụng','primary')}${btn('clear-filters','Xoá lọc','ghost')}</div></form></details><div id="active-filters" class="row"></div>`;
V.R02=(s)=>`${bread('Tất cả tác phẩm')}<p class="eyebrow">Kho tác phẩm</p><h1>Mỗi câu, một lối đọc.</h1><p class="muted">Tìm theo thể loại, hình thức, chủ đề hoặc nơi lưu truyền.</p>${filterControls()}<div class="row between"><p id="catalog-count" class="small muted">38 tác phẩm mẫu · 30 bài mỗi trang</p><div><label class="sr-only" for="sort">Sắp xếp</label><select id="sort"><option value="az">A–Z</option><option value="new">Mới thêm</option></select></div></div>${s==='error'?notice('Chưa cập nhật được kết quả. Các lựa chọn của bạn vẫn còn. '+btn('apply-filters','Thử lại','compact'),'error'):''}<div id="catalog-list" class="grid">${s==='empty'?'':(s==='last'?fixtures.slice(30):s==='filtered'?fixtures.filter(p=>p.genre==='Ca dao'):fixtures.slice(0,30)).map(card).join('')}</div>${s==='empty'?empty('Chưa có bài khớp các bộ lọc','Thử bỏ một lựa chọn hoặc xoá toàn bộ bộ lọc.',btn('clear-filters','Xoá lọc','primary')):''}<nav class="pagination" aria-label="Phân trang">${btn('page','1',s==='last'?'':'primary','data-page="1"')}${btn('page','2',s==='last'?'primary':'','data-page="2"')}</nav>`;
V.R03=(s)=>{let genre={'ca-dao':'Ca dao','tuc-ngu':'Tục ngữ – Thành ngữ','dong-dao':'Đồng dao','cau-do':'Câu đố',ve:'Vè'}[s]||'Ca dao';let list=fixtures.filter(x=>x.genre===genre);return `${bread(genre)}<p class="eyebrow">Đọc theo thể loại</p><h1>${genre}</h1>${s==='missing'?'':'<p class="muted">Lời dẫn thể loại mẫu, dành chỗ cho phần giới thiệu do người biên soạn viết.</p>'}${section('Bài tiêu biểu',`<div class="grid two">${list.slice(0,2).map(card).join('')}</div>`)}${s==='tuc-ngu'?section('Tra theo chữ cái',alpha()):s==='dong-dao'?section('Từ câu hát đến trò chơi',gameParams()+link('R17','Chọn trò theo tuổi & số bé '+icon('arrow'),'btn primary')):s==='cau-do'?section('Mở một lượt đố',link('R16','Đố vui · 10 câu','btn primary')+'<div class="row" style="margin-top:16px">'+['Đồ vật mẫu','Con vật mẫu','Cây cối mẫu'].map(t=>link('R16',t,'chip')).join('')+'</div>'):s==='ve'?notice('Bối cảnh được gắn theo tư liệu của từng bài. Bộ mẫu chưa có sự kiện đã xác nhận nên không tạo lối vào theo sự kiện.'):link('R04','Đọc theo hình thức lục bát '+icon('arrow'),'btn ghost','state=form')}${section('Chủ đề phổ biến',`<div class="row">${['Lao động','Học tập','Thiên nhiên'].map(t=>link('R04',t,'chip')).join('')}</div>`)}${section('Các tác phẩm',`<div class="grid">${list.map(card).join('')}</div>`)}`;};
V.R04=(s)=>{let type={topic:'Chủ đề',region:'Nơi lưu truyền',motif:'Mô-típ',form:'Hình thức'}[s]||'Chủ đề';return `${bread(type)}<p class="eyebrow">${type}</p><h1>${s==='region'?'Vùng lưu truyền mẫu':s==='motif'?'Nhóm mở đầu mẫu':s==='form'?'Lục bát':'Lao động'}</h1><p class="muted">${s==='region'?'Nơi lưu truyền phải có căn cứ riêng. Địa danh được nhắc trong lời là một quan hệ khác.':s==='motif'?'Tên nhóm và lời dẫn mẫu minh hoạ quyết định của người biên soạn; không là kết luận học thuật.':s==='form'?'Thể thơ: Lục bát. Chưa có dữ liệu lối hát, nên không hiển thị lối hát.':'Đọc liền các bài trong cùng chủ đề, giữ lại những câu bạn muốn dùng.'}</p>${fixtures.slice(0,8).map((p,i)=>collectionItem(p,i+1)).join('')}${section('Tuyển tập liên quan',link('R11','Lao động — 8 câu mẫu '+icon('arrow'),'btn'))}`;};
V.R07=(s)=>{const count=s==='lines990'?990:s==='lines220'?220:60,no=s==='no-toc';const sections=Array.from({length:Math.ceil(count/20)},(_,k)=>`<section id="kho-${k+1}" class="long-section">${no?'':`<h2>Khổ ${k+1}</h2>`}${verse(Array.from({length:Math.min(20,count-k*20)},(_,n)=>`Khổ ${k+1} dòng mẫu số ${n+1}`),'',false,false,{nhom:'tp-5'})}${btn('bookmark-position','Nhớ chỗ này','compact ghost',`data-section="kho-${k+1}"`)}</section>`);const main=`${no?'':blockDetails('Mục lục · '+Math.ceil(count/20)+' khổ',`<div class="row">${sections.map((_,i)=>`<a href="#kho-${i+1}" data-action="toc" data-section="kho-${i+1}" class="chip">Khổ ${i+1}</a>`).join('')}</div>`,false,'','tim')}<div class="actions">${btn('resume',icon('clock')+'Đọc tiếp từ chỗ cũ','compact')}</div>${verseCard(`${sections[0]}${level()}<details class="disclosure" id="full-poem"><summary>Đọc toàn bài · còn ${count-20} dòng</summary><div class="detail-body">${sections.slice(1).join('')}</div></details>`,{url:workUrl(fixtures[4]),label:'Lời'})}`;const rest=`${blockDetails('Chú giải','<p>Chú giải mẫu của bài dài, dùng kiểm khả năng đọc tiếp.</p>',false,'','vang')}${footerOfWork(fixtures[4])}`;return workPage({crumb:bread('Vè mẫu dài'),tags:[['Vè'],[count+' dòng',1]],title:'Vè mẫu dài',sub:`${count} dòng · ${Math.ceil(count/12)} phút đọc thử · ${Math.ceil(count/20)} khổ`,main,id:'tp-5',railExtra:`<button type="button" class="btn chi-rong" data-action="print">${icon('print')}<span class="nhan">In</span></button>`,rest});};
const answerImage=()=>`<figure style="margin:16px 0"><svg role="img" aria-label="Hình học thử để kiểm bố cục ảnh đáp án" viewBox="0 0 320 180" style="width:100%;max-width:320px;border-radius:10px" width="320" height="180"><rect width="320" height="180" fill="#EDE6FB"/><circle cx="160" cy="90" r="48" fill="#5E3AAE"/><path d="M113 90h94M160 43v94" stroke="#FFFFFF" stroke-width="2"/></svg><figcaption class="small muted">Đồ hoạ thử của bộ prototype · CC BY 4.0. Không phải ảnh tư liệu.</figcaption></figure>`;
V.R09=(s)=>{const main=verseCard(`${verse(['Câu đố mẫu dòng một','Câu đố mẫu dòng hai'],'',false,false,{nhom:'tp-4'})}<p class="riddle-q">Là cái gì?</p>${level()}${s==='no-hint'?'':details('Gợi ý','<p>Gợi ý tổng hợp để kiểm tương tác mở từng lớp.</p>')}<details class="answer"><summary>Hiện đáp án</summary><div class="detail-body"><h2>Đáp án mẫu</h2>${s==='image'?answerImage():''}<p>Lời giải mẫu cho bố cục; không phải giải một câu đố thật.</p></div></details>${link('R16','Đố bạn bè '+icon('arrow'),'btn')}`,{url:workUrl(fixtures[3]),label:'Câu đố'});const rest=`${section('Câu đố cùng đáp án',link('R09','Câu đố mẫu khác '+icon('arrow')))}${footerOfWork(fixtures[3])}`;return workPage({crumb:bread('Câu đố mẫu'),tags:[['Câu đố'],...(s==='no-hint'?[]:[['Có gợi ý',1]])],title:'Câu đố mẫu',sub:'2 dòng · đáp án thu gọn',main,id:'tp-4',rest});};
V.R10=(s)=>`${bread('Tuyển tập','R01','Khám phá')}<p class="eyebrow">Đọc liền</p><h1>Một chủ đề, nhiều lời.</h1><p class="muted">Tuyển tập ghép từ những trang tác phẩm, để bạn đọc theo mạch và trích dẫn từng câu.</p><div class="row">${[['topic','Chủ đề'],['occasion','Theo dịp'],['situation','Tình huống'],['lesson','Bài học']].map(([v,t])=>link('R10',t,'chip '+(s===v?'selected':''),'state='+v)).join('')}</div>${s==='empty'?empty('Chưa có tuyển tập đủ điều kiện','Chỉ hiện khi có lời dẫn và ít nhất 8 tác phẩm đã đăng.',link('R02','Đọc từ kho tác phẩm','btn')):section(s==='occasion'?'Theo dịp':s==='situation'?'Cho một tình huống':s==='lesson'?'Đọc theo bài học':'Chủ đề để bắt đầu',`<div class="grid">${(s==='occasion'?['Dịp mẫu gần nhất','Dịp mẫu tiếp theo']:s==='situation'?['Ghi nhớ một điều','Gửi một lời nhắn']:s==='lesson'?['Học tập','Lao động']:['Về mẹ','Về cha','Quê hương','Học tập','Lao động','Thiên nhiên']).map((t,i)=>`<article class="card collection-card"><span class="tag">Tuyển tập mẫu</span><h2>${link('R11',t)}</h2><p>8 câu · lời dẫn mẫu để kiểm điều kiện công khai.</p>${link('R11','Đọc liền '+icon('arrow'),'btn ghost')}</article>`).join('')}</div>`)}`;
V.R13=(s)=>`${bread('Từ điển','R01','Tra cứu')}<p class="eyebrow">Tra cứu</p><h1>Hiểu thêm một chữ.</h1><form data-dictionary class="search-form"><label class="sr-only" for="dictionary-q">Tìm mục từ</label><input id="dictionary-q" type="search" placeholder="Tìm một từ hoặc địa danh">${btn('dictionary-search',icon('search')+'Tìm','primary')}</form>${section('Theo chữ cái',alpha())}<div class="row">${['Tất cả','Từ cổ','Hán Việt','Phương ngữ','Địa danh','Vùng'].map(t=>`<button class="chip" data-action="dict-filter">${t}</button>`).join('')}</div><div id="dictionary-results">${s==='empty'?empty('Chưa có mục từ phù hợp','Thử một chữ cái hoặc loại khác.'):['chút','bến Mẫu Bắc','chợ Mẫu Nam'].map((t,i)=>`<div class="list-row"><div><span class="tag">${i?'Địa danh tổng hợp':'Chú thích mẫu'}</span><h2>${link('R14',t,'','state='+(i?'place':'word'))}</h2><p class="muted">${i?'Địa danh tổng hợp để xem bố cục tra cứu.':'Chú thích tổng hợp để xem giao diện.'}</p></div>${link('R14','Xem '+icon('arrow'),'btn ghost','state='+(i?'place':'word'))}</div>`).join('')}</div>`;
V.R14=(s)=>`${bread(s==='place'?'bến Mẫu Bắc':s==='person'?'Nhân vật mẫu':'chút','R13','Từ điển')}<p class="eyebrow">${s==='place'?'Địa danh · tổng hợp':s==='person'?'Nhân vật · tổng hợp':'Mục từ'}</p><h1>${s==='place'?'bến Mẫu Bắc':s==='person'?'Nhân vật mẫu':'chút'}</h1><p>${s==='place'?'Địa danh tổng hợp ở phía bắc để xem bản đồ.':s==='person'?'Nhãn kiểm bố cục mục từ nhân vật. Hồ sơ thật chưa được cung cấp.':'Chú thích tổng hợp để xem giao diện (từ có trong lời: chạm để xem).'}</p><p class="small muted">Nguồn tham khảo đã ẩn theo ${link('R27','chính sách thu thập dữ liệu')}.</p>${s==='place'?notice('Được nhắc đến trong lời. Không đồng nghĩa là nơi lưu truyền. '+link('R15','Xem danh sách địa danh')):''}${section(s==='place'?'Các bài nhắc đến bến Mẫu Bắc':'Các tác phẩm có từ này',`<div class="grid two">${(s==='place'?[fixtures[2],fixtures[12]]:s==='person'?[]:[fixtures[0],fixtures[5]]).map(card).join('')}</div>`)}${section('Tra thêm',link('R14','chợ Mẫu Nam','btn ghost','state=place'))}${btn('back','Quay lại bài đang đọc','ghost')}`;
V.R15=(s)=>`${bread('Bản đồ','R01','Khám phá')}<p class="eyebrow">Vùng & địa danh</p><h1>Lần theo những địa danh.</h1><p class="muted">Danh sách xếp Bắc → Nam. Mỗi địa danh mở các bài <strong>nhắc đến</strong> nơi đó.</p><label for="map-region">Chọn vùng</label><select id="map-region"><option value="all">Tất cả</option><option value="north">Bắc</option><option value="south">Nam</option></select><div class="grid two map-grid section"><div id="map-list">${['bến Mẫu Bắc','chợ Mẫu Nam'].map((t,i)=>`<div class="list-row" data-region="${i?'south':'north'}"><div><span class="tag">Được nhắc đến · địa danh tổng hợp</span><h2>${link('R14',t,'','state=place')}</h2>${link('R08','Mở đồng dao có địa danh '+icon('arrow'))}</div></div>`).join('')}</div><div class="map-area"><h2>Bản đồ đang chờ tài sản phù hợp</h2><p class="muted">Bản xem này giữ danh sách địa danh để tra cứu. Cần dùng SVG đúng của dự án, có Hoàng Sa và Trường Sa.</p><p class="small">Không tự vẽ lại địa giới để lấp chỗ trống.</p></div></div>`;
V.R16=(s)=>`${bread('Đố vui','R01','Khám phá')}<p class="eyebrow">Cùng nhau khám phá</p><h1>Mở một lượt đố vui.</h1><div class="field-grid"><div>${select('quiz-topic','Chủ đề đáp án',['Bộ câu đố tổng hợp','Đồ vật mẫu','Con vật mẫu'])}</div><div>${select('quiz-level','Độ khó',['Dễ · dữ liệu thử','Vừa · dữ liệu thử'])}</div></div><p class="small muted">Bộ kiểm thử 10 bản ghi dùng lời tổng hợp; không phải bộ câu đố văn hoá đã duyệt.</p>${s==='insufficient'?empty('Chưa đủ 10 câu cho lựa chọn này','Chọn một nhóm khác để tiếp tục.',link('R16','Chọn bộ mẫu','btn primary')):s==='complete'?empty('Đã đi hết 10 câu.','Bạn có thể mở một lượt khác hoặc đọc đầy đủ từng bài.',btn('quiz-restart','Đố thêm một lượt','primary')):`<div id="quiz"><p class="eyebrow" id="quiz-progress" aria-live="polite">Câu 1 / 10</p>${Array.from({length:10},(_,i)=>`<article class="quiz-item" data-quiz="${i}"><div class="progress"><span style="width:${(i+1)*10}%"></span></div>${verse(['Câu đố mẫu dòng một','Câu đố mẫu dòng hai'],'',false)}${details('Gợi ý','<p>Gợi ý tổng hợp để kiểm tương tác.</p>')}<details class="answer"><summary>Hiện đáp án</summary><div class="detail-body"><h2>Đáp án mẫu</h2></div></details><div class="actions">${btn('quiz-next',i===9?'Hoàn tất lượt':'Câu khác '+icon('arrow'),'primary')}${link('R09','Xem bài đầy đủ','btn ghost')}</div></article>`).join('')}</div>`}`;
V.R17=(s)=>`${bread('Trò chơi','R01','Khám phá')}<p class="eyebrow">Cùng bé chơi</p><h1>Chọn một trò vừa với các bé.</h1><div class="filters"><div class="field-grid"><div>${input('game-age','Độ tuổi',s==='filtered'?'5':'','number')}</div><div>${input('game-people','Số trẻ',s==='filtered'?'4':'','number')}</div><div>${select('game-place','Nơi chơi',['Tất cả','Trong nhà','Ngoài trời'])}</div><div>${select('game-tools','Đồ dùng',['Tất cả','Không cần','Có đồ dùng'])}</div></div><div class="actions">${btn('filter-games','Tìm trò phù hợp','primary')}${btn('clear-games','Xoá lọc','ghost')}</div></div><p id="game-status" class="small muted" aria-live="polite">Thông số trong bộ mẫu là dữ liệu thử.</p><div id="game-results">${s==='empty'?empty('Chưa có trò phù hợp','Thử thay đổi số trẻ hoặc nơi chơi.'):`<article class="card"><span class="eyebrow">Trò chơi mẫu</span><h2>${link('R18','Cùng đọc đồng dao mẫu')}</h2>${gameParams()}<p>Đi kèm: ${link('R08','Đồng dao mẫu')}</p>${link('R18','Xem cách chơi '+icon('arrow'),'btn primary')}</article>`}</div>`;
V.R18=(s)=>`${bread('Trò chơi mẫu','R17','Trò chơi')}<p class="eyebrow">Cùng bé chơi</p><h1>Trò chơi mẫu</h1>${s==='partial'?'<dl class="params"><div><dt>Số người</dt><dd>4–8 bạn</dd></div></dl>':gameParams()}${section('Cách chơi',gameSteps())}<p class="small muted">Nguồn cách chơi: fixture của dự án. Cần hồ sơ nguồn và giấy phép thật khi thay bằng nội dung thật.</p>${section('Các bài đồng dao đi kèm',card(fixtures[2])+`<div class="actions">${btn('kids',icon('book')+'Đọc cùng bé','primary')}${link('R08','Mở trang đồng dao','btn ghost')}</div>`)}${section('Trò chơi tương tự',link('R17','Tìm theo tuổi, số người & nơi chơi '+icon('arrow')))}`;
V.R19=(s)=>`${bread('Hay bị nhầm','R01','Tra cứu')}<p class="eyebrow">Đọc có đối chiếu</p><h1>Hay bị nhầm là ca dao</h1>${s==='under-gate'?empty('Trang chưa đủ điều kiện công khai','Cần ít nhất 5 câu được gắn cờ, có lý do; trạng thái chỉ có trong môi trường thiết kế.'):notice('5 trường hợp tổng hợp để thử cách trình bày cờ. Không phải kết luận về tác giả hoặc niên đại của câu có thật.')+fixtures.slice(30,35).map((p,i)=>`<article class="section">${flag()}<h2>${link(p.route,p.title,'','item='+p.id+(p.route==='R05'?'&state=flag':''))}</h2>${verse(p.lines,'',false)}<p><strong>Lý do mẫu ${i+1}:</strong> ${['Cần đối chiếu xuất xứ.','Cần kiểm việc gán thể loại.','Chưa có tư liệu về quá trình lưu truyền.','Có thông tin nguồn cần xem thêm.','Cần kiểm hồ sơ tác giả trước khi kết luận.'][i]}</p><p class="small muted">Nguồn của lý do: Nguồn mẫu · example.org (dữ liệu thử).</p></article>`).join('')}`;
V.R20=(s)=>`${bread('Một câu ngẫu nhiên','R01','Khám phá')}<p class="eyebrow">Mở một trang bất chợt</p><h1>Một câu ngẫu nhiên</h1>${s==='empty'?empty('Chưa có bài đủ điều kiện','Trở về kho để đọc các tác phẩm đã có.',link('R02','Mở kho tác phẩm','btn primary')):`<div id="random-work">${verse()}${level()}${meaning()}</div><div class="actions">${btn('random','Câu khác '+icon('arrow'),'primary')}${link('R05','Xem đầy đủ','btn ghost')}</div><p class="small muted">Không lặp trong phiên. Không chọn bài có cờ nghi.</p>`}`;
V.R21=(s)=>`${bread('Đã lưu','R01','Thư viện của bạn')}<p class="eyebrow">Giữ để đọc lại</p><h1>Những câu đã lưu.</h1><p class="muted">Danh sách được lưu trên trình duyệt này. Xoá dữ liệu trình duyệt sẽ làm mất danh sách.</p>${s==='blocked'?notice('Bộ nhớ trình duyệt đang bị chặn. Không thể lưu thay đổi; bạn vẫn có thể đọc và sao chép trích dẫn.','error'):''}${s==='removed'?notice('Một bài đã lưu hiện không còn công khai. '+btn('remove-unavailable','Bỏ mục không còn công khai','compact')):''}<label for="saved-genre">Lọc thể loại</label><select id="saved-genre"><option>Tất cả</option><option>Ca dao</option><option>Tục ngữ – Thành ngữ</option><option>Đồng dao</option><option>Câu đố</option><option>Vè</option></select><div id="saved-list" class="section">${empty('Giữ lại một câu để đọc sau.','Bấm Lưu ở tác phẩm bạn muốn giữ.',link('R02','Mở kho tác phẩm','btn primary'))}</div>`;
V.R22=(s)=>`${bread('Góp tư liệu')}<p class="eyebrow">Cùng làm đầy trang sách</p><h1>Bạn muốn góp gì?</h1><p class="muted">Không cần tên thật, email hay số điện thoại. Nội dung gửi sẽ chờ người biên soạn xem.</p>${s==='success'?notice('Đã nhận nội dung mẫu. Đang chờ biên soạn / duyệt; chưa xuất hiện công khai.','success'):''}<form id="contribution-form" novalidate><label for="contribution-type">Loại đóng góp</label><select id="contribution-type">${['Ở quê nói khác','Góp ý chú thích','Báo lỗi','Gửi số trang','Cảm nghĩ ngắn','Viết cảm nhận / bài phân tích'].map((t,i)=>`<option value="${i}">${t}</option>`).join('')}</select><div data-for-type="5">${input('contribution-title','Tiêu đề bài viết')}${input('contribution-alias','Bút danh — không bắt buộc')}</div><div data-for-type="3">${input('contribution-book','Tên sách — để trống nếu chưa biết')}${input('contribution-page','Số trang')}${input('contribution-note','Thông tin bổ sung bạn muốn cung cấp')}</div>${area('contribution-content','Nội dung',s==='error'?'Nội dung mẫu đang nhập được giữ lại khi lỗi mạng.':'')}<p class="small muted">Giữ nguyên lời bạn đọc được. Với bài phân tích, xuống dòng để tách đoạn; không đưa thông tin cá nhân không cần thiết.</p>${input('contribution-origin','Xuất xứ — không bắt buộc')}<label class="choice"><input id="consent" type="checkbox">Tôi cam kết tự viết phần đóng góp và đồng ý CC BY 4.0</label>${s==='turnstile'?notice('Vùng kiểm chống rác khi cấu hình Turnstile. Mẫu thiết kế chưa tải dịch vụ hoặc dùng khoá thật.'):''}<p id="form-error" class="small" style="color:var(--son)" aria-live="polite">${s==='validation'?'Bạn chưa nhập nội dung.':s==='error'?'Chưa gửi được. Nội dung vẫn được giữ; hãy thử lại.':s==='rate-limit'?'Bạn đã gửi quá giới hạn. Giữ lại nội dung và thử vào lúc khác.':''}</p><div class="actions"><button type="submit" class="btn primary">Gửi</button></div><p class="small muted">Đọc ${link('R28','Quyền riêng tư')} và cách yêu cầu gỡ. Nơi hoặc người kể chỉ ghi khi có căn cứ và sự đồng ý cần thiết.</p></form>`;
V.R23=(s)=>`${bread('Một cách đọc bài mẫu')}<p class="eyebrow">Cảm nhận – phân tích</p><h1>Một cách đọc bài mẫu</h1>${s==='no-alias'?'':'<p class="small muted">Bút danh mẫu · dữ liệu thử</p>'}<article><p>Đây là nội dung tổng hợp để kiểm cách trình bày bài cảm nhận đã duyệt. Phần người viết bàn luận được tách rõ khỏi lời tác phẩm.</p><blockquote style="margin:32px 0;padding-left:24px;border-left:2px solid var(--son)">${verse(poem.slice(0,2),'lucbat',false)}<p class="small">Trích tác phẩm mẫu · ${link('R05','Xem bài')}</p></blockquote><h2>Đọc lời và xem mức kiểm</h2><p>Vùng này dành cho các đoạn phân tích do người viết cung cấp. Bài phân tích không được nhập vào Ý nghĩa, không tự thay đổi mức độ hoàn thiện của tác phẩm.</p></article>${section('Tác phẩm đang bàn',card(fixtures[0]))}<p class="small muted">Nội dung tổng hợp để kiểm giao diện · CC BY 4.0.</p>`;
V.R24=()=>`${bread('Phương pháp','R01','Về thư viện')}<p class="eyebrow">Tin, hiểu, cảm</p><h1>Cách chúng tôi biên soạn.</h1>${details('Trong trang này','<p><a href="#muc-kiem">Dòng nhỏ dưới lời nói gì</a></p><p><a href="#nguon-lop">Thông tin tư liệu theo lớp</a></p><p><a href="#vai-tro-ai">Vai trò của AI</a></p>')}<section class="section" id="muc-kiem"><h2>Dòng nhỏ dưới lời nói gì?</h2><p>“Lời theo bản lưu truyền phổ biến · chưa đối chiếu sách” nói về mức đối chiếu lời. Nó không khẳng định một bản duy nhất và không thay cho việc đánh giá phần nghĩa.</p>${level()}<p>Khi đã được người xác nhận, dòng mức kiểm nêu tên sách và số trang.</p>${level(true)}</section><section class="section" id="nguon-lop"><h2>Mỗi lớp, một nguồn.</h2><p>Lời, nghĩa, chú thích, cách chơi và ảnh có thông tin nguồn riêng. Việc hiển thị nguồn theo chính sách của hồ sơ nguồn; ghi công nguồn mở đặt ngay tại phần được dùng.</p>${materials()}</section><section class="section" id="vai-tro-ai"><h2>Máy hỗ trợ, người quyết.</h2><p>Máy có thể đề xuất và soạn nháp nghĩa. Người biên soạn đọc, sửa và quyết định duyệt. Lời và dị bản không được tạo bằng AI để lấp phần thiếu.</p></section>${contribute()}`;
V.R25=(s)=>`${bread('Nguồn','R01','Về thư viện')}<p class="eyebrow">Theo từng lớp nội dung</p><h1>Nguồn được ghi nhận.</h1>${s==='empty'?empty('Chưa có hồ sơ nguồn được phép hiện','Nội dung nguồn công khai sẽ được bổ sung theo chính sách.'):notice('Danh mục thật cần mang từ MVP và được chủ dự án duyệt. Dưới đây là mẫu cấu trúc ghi công.')+`<div class="list-row"><div><span class="tag">Nguồn mẫu · hồ sơ tổng hợp</span><h2>Nguồn mẫu</h2><p>Địa chỉ thử: example.org. Tác giả, năm, quyền sử dụng: chưa rõ.</p><p class="small muted">Không đưa nguồn đang ẩn vào danh sách này.</p></div></div>`}${link('R27','Chính sách thu thập dữ liệu '+icon('arrow'),'btn ghost')}`;
V.R26=()=>`${bread('Về dự án','R01','Thư viện')}<p class="eyebrow">Phongdao</p><h1>Thư viện Văn học<br>Dân gian Việt Nam.</h1><p class="serif" style="font-size:28px">Đọc một câu. Hiểu một đời sống.</p><p>Mỗi câu ghi rõ lấy từ đâu, và đã được kiểm đến mức nào.</p><p>Phi lợi nhuận, không quảng cáo, không theo dõi; đọc tốt trên điện thoại.</p>${section('Năm thể loại lõi','<p>Ca dao; Tục ngữ – Thành ngữ; Đồng dao; Vè; Câu đố.</p>')}${section('Cùng gìn giữ lời và dị bản','<p>Mỗi tác phẩm có một trang riêng. Tuyển tập, chủ đề và lớp học ghép từ các tác phẩm, dùng lại nghĩa đã biên soạn.</p>'+link('R24','Xem phương pháp '+icon('arrow'),'btn'))}${contribute()}`;
const policy=(name,heads)=>`${bread(name,'R01','Về thư viện')}<p class="eyebrow">Thông tin dự án</p><h1>${name}</h1>${notice('Nội dung chờ cung cấp: cần mang trang chính sách hiện hành từ MVP và được chủ dự án duyệt. Đây là cấu trúc thiết kế, không phải chính sách đã ban hành.')}<nav aria-label="Mục lục">${heads.map((t,i)=>`<p><a href="#policy-${i}">${t}</a></p>`).join('')}</nav>${heads.map((t,i)=>`<section class="section" id="policy-${i}"><h2>${t}</h2><p class="muted">Vị trí dành cho nội dung hiện hành được chủ dự án cung cấp và xác nhận.</p></section>`).join('')}`;
V.R27=()=>policy('Chính sách thu thập dữ liệu',['Nguồn và phạm vi thu thập','Ghi nhận nguồn theo từng lớp','Chính sách hiện nguồn','Tiếp nhận yêu cầu điều chỉnh']);V.R28=()=>policy('Quyền riêng tư',['Tuỳ chọn lưu trên trình duyệt','Nội dung người đọc chủ động gửi','Chống rác khi được cấu hình','Cách yêu cầu gỡ nội dung']);
V.R29=()=>`<div class="hero"><p class="eyebrow">404</p><h1>Chưa tìm thấy trang này.</h1><p class="muted">Bạn có thể tìm lại vài chữ trong đường dẫn, hoặc mở một lối đọc khác.</p><form class="search-form" data-search action="R12.html"><label class="sr-only" for="not-found-q">Từ khoá từ đường dẫn</label><input id="not-found-q" name="q" value="cau mau"><button type="submit" class="btn primary">Tìm</button></form><div class="actions">${link('R02','Kho tác phẩm','btn')}${link('R10','Tuyển tập','btn')}${link('R13','Từ điển','btn')}</div></div>`;
V.R30=(s)=>`<div class="hero"><p class="eyebrow">Phongdao</p><h1>${s==='error'?'Chưa tải được nội dung.':'Thư viện đang được nâng cấp.'}</h1><p class="muted">${s==='error'?'Bạn có thể thử lại hoặc trở về một trang đọc cơ bản.':'Xin bạn quay lại sau. Chúng tôi chưa có thời gian kết thúc được xác nhận.'}</p>${s==='error'?`<div class="actions">${btn('reload-page','Thử lại','primary')}${link('R02','Mở kho tác phẩm','btn')}</div>`:''}</div>`;
V.R31=(s)=>`<p class="eyebrow">Khám phá</p><h1>Bạn muốn đọc gì?</h1><form class="search-form big" data-search action="R12.html"><label for="kp-q" class="sr-only">Tìm câu bạn nhớ</label><input id="kp-q" type="search" name="q" placeholder="Gõ câu bạn nhớ…">${btn('submit-search',icon('search')+' Tìm','primary')}</form>${section('Theo thể loại',`<div class="tiles">${[['R02','Tất cả','layers','tat-ca',''],['R03','Ca dao','book','ca-dao','state=ca-dao'],['R03','Tục ngữ – Thành ngữ','quote','tuc-ngu','state=tuc-ngu'],['R03','Đồng dao','kids','dong-dao','state=dong-dao'],['R03','Vè','layers','ve','state=ve'],['R03','Câu đố','spark','cau-do','state=cau-do']].map(([r,t,i,g,q])=>link(r,`<span class="entry-icon">${icon(i)}</span><strong>${t}</strong>`,'tile g-'+g,q)).join('')}</div>`)}${section('Lối đọc',`<div class="start-grid">${[['R10','Tuyển tập','layers','Đọc liền một chủ đề, trình chiếu cả bộ',''],['R10','Theo dịp','calendar','Tết, Vu Lan, 20/11…','state=occasion'],['R04','Chủ đề','tag','Mẹ, quê hương, lao động…',''],['R15','Vùng & Bản đồ','map','Nơi lưu truyền, địa danh trong lời',''],['R04','Mô-típ','spark','“Thân em như…”, “Chiều chiều…”','state=motif'],['R20','Một câu ngẫu nhiên','compass','Mở một trang bất chợt','']].map(([r,t,i,d,q])=>link(r,`<span class="entry-icon">${icon(i)}</span><h3>${t}</h3><p>${d}</p>`,'card start-card g-dip',q)).join('')}</div>`)}${section('Tra cứu',[['R12','Tìm'],['R13','Từ điển'],['R19','Hay bị nhầm là ca dao'],['R24','Phương pháp & nguồn']].map(([r,t])=>link(r,`<span>${t}</span>`+icon('arrow'),'genre-row')).join(''))}${section('Về thư viện',[['R26','Về dự án'],['R27','Chính sách thu thập dữ liệu'],['R28','Quyền riêng tư'],['R22','Góp tư liệu']].map(([r,t])=>link(r,`<span>${t}</span>`+icon('arrow'),'genre-row')).join(''))}${s==='eligible'?section('Mẫu điều hướng khi đợt 5 đủ điều kiện',link('F01','<span>Cho lớp học</span>'+icon('arrow'),'genre-row')+link('F06','<span>Nghe</span>'+icon('arrow'),'genre-row')):''}`;
V.A03=(s)=>`<p class="eyebrow">Tác phẩm</p><div class="row between"><h1>Những trang đang biên soạn.</h1>${link('A04','Thêm tác phẩm','btn primary')}</div><div class="filters"><label for="admin-search">Tìm tên hoặc lời</label><input id="admin-search" type="search" placeholder="Tìm tác phẩm mẫu"><div class="field-grid"><div>${select('admin-genre','Thể loại',['Tất cả','Ca dao','Tục ngữ – Thành ngữ','Đồng dao','Vè','Câu đố'])}</div><div>${select('admin-level','Cấp nội bộ — tự tính',['Tất cả','L0','L1','L2','L3'])}</div><div>${select('admin-lack','Thiếu lớp',['Tất cả','Thiếu nghĩa','Thiếu chủ đề','Thiếu vùng','Có cờ nghi'])}</div><div>${select('admin-sort','Sắp xếp',['Đọc nhiều','Mới thêm','A–Z'])}</div></div>${btn('admin-filter','Lọc','primary')}</div><div id="admin-results">${s==='empty'?empty('Chưa có tác phẩm phù hợp','Thử bỏ một bộ lọc.'):fixtures.slice(0,10).map((p,i)=>`<article class="task" data-admin-fixture="${p.id}"><div><span class="tag">${p.genre} · ${p.meaning?'L2':'L1'}</span><h3>${p.title}</h3><p><span class="status ${i===6?'pending':''}">${i===6?'Nháp người viết':i===7?'Ẩn':'Đã đăng'}</span>${!p.meaning?' · Thiếu nghĩa':''}</p></div>${link('A04','Soạn '+icon('edit'),'btn compact','item='+p.id)}</article>`).join('')}</div><div class="actions">${link('A20','Cần xem sau chuyển dữ liệu','btn ghost')}${link('A19','Gộp hai tác phẩm','btn ghost')}</div>`;
const editorSection=(n,t,b)=>`<section class="editor-section" id="editor-${n}"><p class="eyebrow">${String(n).padStart(2,'0')}</p><h2>${t}</h2>${b}</section>`;
V.A04=(s)=>`<p class="eyebrow">Soạn tác phẩm có cấu trúc</p><h1>Dòng mẫu một của bài</h1><p class="small muted">${s==='candidate'?'Ứng viên từ kho · chưa là tác phẩm công khai':'Tác phẩm đã đăng'} · Không có thay đổi được lưu tự động.</p><form id="editor-form"><div class="field-grid"><div>${input('work-title','Tên tác phẩm','Dòng mẫu một của bài')}</div><div>${select('work-genre','Thể loại',['Ca dao','Tục ngữ – Thành ngữ','Đồng dao','Vè','Câu đố'])}</div></div><div class="actions">${btn('save-draft','Lưu nháp')}${btn('publish',s==='candidate'?'Đăng tác phẩm':'Cập nhật','primary',s==='expired'?'disabled aria-describedby="editor-status"':'')}${link('R05','Xem trang','btn ghost')}</div><div id="editor-status" aria-live="polite">${['error','offline','expired','conflict'].includes(s)?notice({error:'Lưu chưa thành công. Giữ phần đang sửa và thử lại.',offline:'Mất kết nối. Phần đang sửa vẫn ở đây; chưa được lưu lên máy chủ.',expired:'Phiên đã hết hạn. Sao chép phần đang sửa trước khi đăng nhập lại bằng WordPress.',conflict:'Có phiên bản mới hơn. Xem trước/sau, không ghi đè bản mới.'}[s],'error'):notice('Nhắc biên tập: thiếu chủ đề, nghi trùng và chú thích chưa neo. Các nhắc này không khoá Cập nhật.')}</div>${editorSection(1,'Lời',area('work-lines','Mỗi dòng nguồn một dòng',poem.join('\n'))+notice('Có thể trùng với “Bài mẫu 06” · '+link('A19','So hai bài')+'<br>Nhắc để bạn kiểm tra; không chặn Đăng.')+'<p class="small muted">Thể thơ nhận được: lục bát · dữ liệu thử.</p>')}${editorSection(2,'Mức kiểm','<p>Chỉ điền khi đã đối chiếu. Để trống khi chưa rõ.</p><div class="field-grid"><div>'+input('book-record','Lời đã đối chiếu với — hồ sơ sách')+'</div><div>'+input('book-page','Trang')+'</div></div>'+input('book-url','Đường dẫn bản đối chiếu'))}${editorSection(3,'Dị bản',`<div id="variant-editor"><div class="card">${area('variant-1','Lời dị bản','Dòng mẫu khác của bài này\nDòng mẫu hai khác dài hơn cho vừa')}<div class="field-grid"><div>${input('variant-place','Nơi lưu truyền')}</div><div>${input('variant-narrator','Người kể — chỉ khi có đồng ý')}</div><div>${input('variant-year','Năm')}</div><div>${input('variant-source','Nguồn')}</div></div><div class="actions">${btn('move-up','Lên','compact')}${btn('move-down','Xuống','compact')}</div></div></div><div class="actions">${btn('add-variant','Thêm dị bản','ghost')}</div>`)}${editorSection(4,'Nghĩa',area('work-meaning','Ý nghĩa',fixtures[0].meaning)+`<label class="choice"><input id="editor-ai" type="checkbox">Có hỗ trợ của AI — do người biên soạn xác nhận</label><div class="ai-draft"><span class="tag">Nháp máy — chưa duyệt</span><p id="draft-meaning">Nháp tổng hợp để thử thao tác nhận nội dung vào vùng biên soạn.</p>${btn('use-draft','Dùng nháp này','compact')}</div>${details('Các lớp của tục ngữ – thành ngữ',area('literal','Nghĩa đen')+area('figurative','Nghĩa bóng')+area('usage','Dùng khi')+input('synonyms','Chọn câu gần nghĩa / trái nghĩa'))}`)}${editorSection(5,'Chú thích',`<div class="card"><span class="tag">Chép từ Nguồn mẫu · nguồn nội bộ</span>${input('annotation-word','Từ','chút')}${area('annotation-text','Lời giải','Chú thích tổng hợp để xem giao diện.')}${input('annotation-source','Hồ sơ nguồn','Nguồn mẫu')}${select('annotation-anchor','Trạng thái neo',['Đã neo vào “chút”','Chưa neo'])}${link('A06','Nối với mục từ “chút”','btn compact ghost')}</div>`)}${editorSection(6,'Theo thể loại',s==='ve'?area('verse-sections','Các đoạn')+area('verse-context','Bối cảnh — chỉ có căn cứ mới điền'):s==='dong-dao'?select('linked-game','Trò chơi liên quan',['Chưa gắn','Trò chơi mẫu']):s==='cau-do'?input('riddle-question','Câu hỏi','Là cái gì?')+input('riddle-answer','Đáp án','Đáp án mẫu')+area('riddle-hint','Gợi ý')+input('riddle-image-credit','Ghi công ảnh — nếu có'):'<p class="muted">Ca dao sử dụng lời, dị bản, chú thích và hình thức ở các vùng trên.</p>')}${editorSection(7,'Phân loại',`<div class="field-grid"><div>${select('work-topic','Chủ đề',['Chưa chọn','Lao động','Học tập'])}</div><div>${input('work-region','Vùng lưu truyền — cần căn cứ')}</div><div>${input('work-motif','Mô-típ')}</div><div>${select('work-form','Hình thức',['Lục bát','Chưa xác định'])}</div></div>${notice('Gợi ý máy: chủ đề “Lao động”. Lý do trong fixture: đang thử thao tác người xác nhận. '+btn('accept-taxonomy','Chấp nhận gợi ý','compact'))}`)}${editorSection(8,'Cờ & SGK',`<label class="choice"><input id="work-flag" type="checkbox">Nghi không phải dân gian</label>${area('flag-reason','Lý do do người biên soạn viết')}${input('flag-source','Nguồn của lý do')}${details('SGK — chỉ khi đã thấy sách',input('sgk-book','Bộ sách')+input('sgk-class','Lớp')+input('sgk-lesson','Bài')+input('sgk-page','Trang'))}`)}${editorSection(9,'Tư liệu',materials()+details('Chỉ người biên soạn thấy','<p>Nguồn đã ẩn: Hồ sơ nguồn mẫu. Bề mặt khách không nhận trường nội bộ này.</p>'))}${editorSection(10,'Lịch sử',link('A18','Xem trước / sau của từng lớp '+icon('arrow'),'btn ghost'))}<div class="actions">${btn('save-draft','Lưu nháp')}${btn('publish',s==='candidate'?'Đăng tác phẩm':'Cập nhật','primary',s==='expired'?'disabled':'')}${btn('copy-edit-buffer','Sao chép phần đang sửa','ghost')}</div></form>`;
V.A05=(s)=>`<p class="eyebrow">Tuyển tập</p><h1>Ghép bài thành một mạch đọc.</h1><form id="collection-editor">${input('collection-name','Tên tuyển tập','Lao động')}<div class="field-grid"><div>${select('collection-type','Loại',['Chủ đề','Theo dịp','Tình huống','Bài học'])}</div><div>${select('collection-audience','Đối tượng',['Không giới hạn','Học sinh','Giáo viên','Phụ huynh'])}</div></div>${area('collection-intro','Lời dẫn — người biên soạn viết',s==='under-gate'?'':'Lời dẫn tổng hợp để kiểm bố cục tuyển tập, không phải nội dung biên soạn thật.')}${notice('<span id="collection-status">'+(s==='under-gate'?'7 câu · thiếu lời dẫn. Chưa đủ 8 câu để công khai.':s==='thirty'?'30 câu · 29 câu có ý nghĩa.':'8 câu · 7 câu có ý nghĩa.')+'</span><br>Không dùng tiêu đề “N câu có giải nghĩa” khi còn câu thiếu nghĩa.')}<label for="collection-add">Tìm tác phẩm để thêm</label><select id="collection-add">${fixtures.map(p=>`<option value="${p.id}">${p.title} · ${p.genre}</option>`).join('')}</select>${btn('add-collection-item','Thêm vào tuyển tập','compact')}<div id="collection-editor-list">${fixtures.slice(0,s==='thirty'?30:s==='under-gate'?7:8).map((p,i)=>`<article class="task" data-collection-id="${p.id}"><div><span class="tag">${p.genre}</span><h3>${p.title}</h3><p>${p.meaning?'Có Ý nghĩa · dùng lại từ bài đơn':'Chưa có ý nghĩa'}</p>${input('fit-'+i,'Hợp khi — ghi chú riêng của mục')}</div><div>${btn('move-up','Lên','compact')}${btn('move-down','Xuống','compact')}${btn('remove-collection-item','Bỏ khỏi tập','compact ghost')}</div></article>`).join('')}</div><div class="actions">${btn('save-collection','Lưu nháp','primary')}${link('R11','Xem trước đọc liền','btn')}${btn('publish-collection','Công khai mô phỏng')}</div></form>`;
V.A06=(s)=>`<p class="eyebrow">Từ điển</p><h1>Một từ, nhiều trang nối lại.</h1><div class="field-grid"><div>${input('term-word','Mục từ','chút')}</div><div>${select('term-type','Loại',['Từ thường','Địa danh','Nhân vật'])}</div></div>${area('term-meaning','Lời giải','Chú thích tổng hợp để xem giao diện.')}${input('term-source','Nguồn lời giải','Nguồn mẫu')}${section('Wikidata',`<div class="card"><span id="entity-status" class="status pending">Chưa xác nhận</span><h2>bến Mẫu Bắc — thực thể tổng hợp</h2><p>Mô tả: địa danh tổng hợp ở phía bắc. Chưa có ảnh và toạ độ đã xác nhận để hiện với người đọc.</p><div class="actions">${btn('entity-right','Đúng','primary')}${btn('entity-wrong','Sai')}${btn('entity-skip','Bỏ qua','ghost')}</div></div>`)}${details('Ảnh và ghi công',input('term-image','Tài sản ảnh có quyền')+input('term-credit','Tác giả / giấy phép / nguồn')+'<label class="choice"><input type="checkbox">Ẩn ảnh</label>')}${section('Tác phẩm dùng từ',link('A04','Dòng mẫu một của bài','btn ghost'))}<div class="actions">${btn('save-local','Lưu mục từ mô phỏng','primary')}${link('R14','Xem bản người đọc','btn')}</div>`;
V.A07=(s)=>`<p class="eyebrow">Trò chơi</p><h1>Thông số trước, nguồn rõ ràng.</h1>${input('game-title-edit','Tên','Trò chơi mẫu')}<div class="field-grid"><div>${input('game-number-edit','Số người','4–8 bạn')}</div><div>${input('game-age-edit','Độ tuổi','4–10 tuổi')}</div><div>${input('game-place-edit','Nơi chơi','Trong nhà — dữ liệu thử')}</div><div>${input('game-tools-edit','Đồ dùng','Không cần')}</div></div>${area('game-steps-edit','Mỗi bước một dòng','Bước mẫu thứ nhất của trò chơi.\nBước mẫu thứ hai: vừa đọc đồng dao vừa chơi.')}${input('game-source-edit','Nguồn đúng bài')}${input('game-license-edit','Giấy phép — chưa rõ thì để trống')}${input('wiki-page','Địa chỉ bài Wikipedia tiếng Việt')}<div class="actions">${btn('fetch-game','Lấy mục Cách chơi từ Wikipedia','primary')}</div><div id="game-fetch-preview">${s==='fetched'?notice('Bản xem thử nội dung lấy về. Nguồn mẫu, không gọi Wikipedia thật. '+btn('accept-game','Dùng nội dung này','compact')):''}</div>${select('game-work-link','Bài đồng dao liên quan',['Đồng dao mẫu','Chưa nối'])}<div class="actions">${btn('save-local','Lưu trò chơi mô phỏng','primary')}${link('R18','Xem trang trò chơi','btn')}</div>`;
V.A08=(s)=>`<p class="eyebrow">Mô-típ</p><h1>Từ cụm mở đầu đến một nhóm đọc.</h1><div class="row">${link('A08','Gợi ý chưa xử lý','chip')}${link('A08','Đã xử lý','chip','state=processed')}</div>${notice(s==='processed'?'Nhóm mẫu đã được người biên soạn đặt tên.':'Máy gom các bài có cụm mở đầu gần nhau. Tên và mô tả do người biên soạn quyết.')}<div class="card"><h2>Nhóm mở đầu “Dòng mẫu…”</h2><p class="small muted">Lý do: cùng cụm mở đầu trong dữ liệu tổng hợp.</p>${fixtures.filter(p=>p.genre==='Ca dao').slice(0,4).map(p=>`<label class="choice"><input type="checkbox" checked>${p.title}</label>`).join('')}</div>${input('motif-name','Tên mô-típ — người đặt')}${area('motif-description','Mô tả — người viết')}<div class="actions">${btn('save-motif','Tạo / lưu mô-típ','primary')}${link('R04','Xem bản người đọc','btn','state=motif')}</div>`;
V.A09=(s)=>`<p class="eyebrow">Phân loại</p><h1>${s==='region'?'Vùng lưu truyền':'Chủ đề của dự án'}</h1><div class="row">${link('A09','Chủ đề','chip')}${link('A09','Vùng','chip','state=region')}${link('A08','Mô-típ','chip')}${link('A10','Thể loại','chip')}</div>${notice(s==='region'?'Vùng lưu truyền cần căn cứ. Địa danh được nhắc đến thuộc mục từ, không suy vùng từ lời.':'Dùng bộ chủ đề của dự án; không tự thêm taxonomy từ tên nguồn.')}<table class="table responsive"><thead><tr><th>Giá trị nguồn</th><th>Giá trị dự án</th><th>Quyết định</th></tr></thead><tbody>${['Lao động','Học tập','Thiên nhiên'].map((t,i)=>`<tr><td data-label="Nguồn">${s==='region'?'Vùng nguồn mẫu '+(i+1):'Chủ đề nguồn mẫu '+(i+1)}</td><td data-label="Dự án">${s==='region'?'Chưa ánh xạ':t}</td><td>${btn('accept-mapping','Xem & xác nhận','compact')}</td></tr>`).join('')}</tbody></table>${area('taxonomy-description','Mô tả — người biên soạn viết')}<div class="actions">${btn('save-local','Lưu mô phỏng','primary')}</div>`;
V.A10=(s)=>`<p class="eyebrow">Thể loại</p><h1>Mỗi thể loại có một lối đọc.</h1>${select('genre-edit','Chọn thể loại lõi',['Ca dao','Tục ngữ – Thành ngữ','Đồng dao','Vè','Câu đố'])}${area('genre-intro','Giới thiệu — người biên soạn viết')}${select('genre-featured','Bài tiêu biểu',['Chưa chọn; dùng L2 đọc nhiều','Dòng mẫu một của bài'])}${notice(s==='zero'?'0 bài đã đăng → ẩn thể loại khỏi menu.':'8 bài mẫu đã đăng · 6 bài L2 tự tính → thể loại lõi hiện trong menu. Không nhập cấp chất lượng bằng tay.')}<div class="actions">${btn('save-local','Lưu thể loại mô phỏng','primary')}${link('R03','Xem trang thể loại','btn')}</div><p class="small muted">Cổng mở thể loại mới thuộc đợt 5.</p>${link('F09','Xem thiết kế cổng đợt 5 '+icon('arrow'))}`;
V.A11=(s)=>`<p class="eyebrow">Nguồn / Hồ sơ nguồn</p><h1>Ghi đúng điều mình biết.</h1><div class="row">${link('A11','Hồ sơ nguồn','chip selected')}${link('A12','Nguồn tự động','chip')}${link('A13','Kho thu thập','chip')}${link('A14','Máy đang làm','chip')}</div><form id="source-form">${input('source-name','Tên nguồn','Nguồn mẫu')}<div class="field-grid"><div>${select('source-type','Loại',['Web','Sách','Người kể','Người đọc','Wiki'])}</div><div>${input('source-author','Tác giả — chưa rõ để trống')}</div><div>${input('source-year','Năm — chưa rõ để trống')}</div><div>${input('source-license','Giấy phép')}</div></div>${select('source-permission','Trạng thái xin phép',['Chưa rõ / chưa xin','Đã gửi','Đồng ý','Từ chối','Không cần'])}${input('source-credit','Mẫu ghi công')}${select('source-policy','Chính sách hiện',['Ẩn với người đọc','Hiện tại chỗ','Trong Thông tin tư liệu'])}<label class="choice"><input id="source-copy" type="checkbox">Chép chú thích</label>${area('source-notes','Ghi chú')}${notice('Đổi ở đây là đổi chính sách — cần ghi quyết định')}<label for="source-decision">Đối chiếu quyết định của dự án</label><input id="source-decision" placeholder="Chưa có quyết định thì giữ chính sách hiện hành"><div class="grid two section"><div class="card"><p class="eyebrow">Người đọc thấy</p><div id="guest-source-preview">${s==='inline'?'<p>Nguồn: Nguồn mẫu · example.org</p>':s==='metadata'?materials():'<p>2 mục · nguồn tham khảo đã ẩn · Chính sách thu thập dữ liệu</p>'}</div><p class="small muted">Bản khách không nhận URL nguồn nội bộ.</p></div><div class="card"><p class="eyebrow">Người biên soạn thấy</p><p>Chỉ người biên soạn thấy dòng này · Nguồn đã ẩn: Hồ sơ nguồn mẫu.</p><p class="small muted">Mẫu riêng; chỉ dữ liệu tổng hợp.</p></div></div><div class="actions">${btn('save-source','Lưu chính sách mô phỏng','primary',s==='editor'?'disabled aria-describedby="source-role"':'')}${link('R05','Mở trang khách','btn')}</div>${s==='editor'?'<p id="source-role" class="notice">Vai Biên tập không đổi hồ sơ nguồn, quyền sử dụng hoặc chính sách hiện.</p>':''}<p id="source-status" aria-live="polite"></p></form>`;
V.A12=(s)=>`<p class="eyebrow">Nguồn / Tự động</p><h1>Thu thập vào kho, người quyết đăng.</h1><label class="choice"><input id="source-enabled" type="checkbox" checked>Bật nguồn mẫu</label><div class="field-grid"><div>${select('source-schedule','Lịch lấy',['Hằng ngày','Tạm dừng'])}</div><div>${input('source-limit','Giới hạn mỗi lượt','10','number')}</div></div>${select('source-genres','Thể loại lấy',['Năm thể loại lõi','Ca dao','Tục ngữ – Thành ngữ'])}${select('source-profile','Hồ sơ nguồn',['Nguồn mẫu'])}<label class="choice"><input type="checkbox" id="auto-copy">Chép chú thích</label><div class="actions">${btn('save-local','Lưu cấu hình mô phỏng')}${btn('fetch-source','Lấy ngay mô phỏng','primary')}</div><div id="source-run-status" aria-live="polite">${notice(s==='error'?'Lần lấy cuối gặp lỗi kết nối. Không có dữ liệu bị tự xuất bản.':'Lần cuối: chưa chạy trong phiên mô phỏng.')}</div>${link('A14','Xem hàng đợi '+icon('arrow'),'btn ghost')}`;
V.A13=(s)=>`<p class="eyebrow">Nguồn / Kho thu thập</p><h1>Kho riêng tư.</h1>${notice('Ứng viên và dữ liệu kho chưa phải tác phẩm công khai. Chỉ người biên soạn thấy bề mặt này.')}<label for="warehouse-q">Tìm trong kho mẫu</label><input id="warehouse-q" type="search"><div class="row section">${link('A13','Ứng viên','chip')}${link('A13','Đã gộp','chip','state=merged')}${link('A12','Theo nguồn','chip')}</div>${[1,2,3].map((n)=>`<article class="task"><div><span class="tag">Nguồn mẫu · ${s==='merged'?'Đã gắn tự động':'Ứng viên'}</span><h3>Bản ghi kho mẫu ${n}</h3><p>${s==='merged'?'Quyết định tự gắn: trùng hệt một dị bản đã ghi. Có thể tách ra để xem lại.':'Nội dung tổng hợp; chưa xuất bản. Tạo thẻ ở cùng Hộp việc.'}</p></div>${s==='merged'?btn('detach','Tách ra','compact'):link('A02','Xem ứng viên','btn compact','state=candidate')}${btn('warehouse-discard','Bỏ / Xem lại','compact ghost')}</article>`).join('')}`;
V.A14=(s)=>`<p class="eyebrow">Máy đang làm</p><h1>Biết việc đang ở đâu.</h1><p class="muted">Trạng thái dưới đây là dữ liệu thử. Không chạy thu thập thật.</p><table class="table responsive"><thead><tr><th>Việc</th><th>Trạng thái</th><th>Lần thử</th><th>Thao tác</th></tr></thead><tbody>${[['Lấy Nguồn mẫu','Lỗi kết nối','2'],['Cập nhật ứng viên','Đang chờ','0'],['Dựng chỉ mục mẫu','Thành công mô phỏng','1']].map(([t,st,n],i)=>`<tr><td>${t}</td><td><span class="status ${i===0?'error':i===1?'pending':''}">${st}</span></td><td data-label="Lần thử">${n}</td><td>${i===0?btn('retry-job','Thử lại','compact'):'—'}</td></tr>`).join('')}</tbody></table>${details('Chi tiết lỗi gần nhất','<p>Không nhận được phản hồi từ nguồn trong thời gian chờ. Thử lại sau; phần đã lấy được giữ nguyên.</p><code>DEMO_CONNECTION_TIMEOUT</code>')}<p id="job-feedback" aria-live="polite"></p>`;
V.A15=(s)=>`<p class="eyebrow">Người đọc gửi</p><h1>Cùng một hộp việc.</h1><p class="muted">Đây là danh sách đầy đủ của các thẻ cũng xuất hiện ở Hôm nay.</p>${s==='empty'?empty('Chưa có nội dung gửi chờ xử lý','Khi có góp ý, bạn sẽ thấy tại đây và Hộp việc.'):['Dị bản','Góp ý chú thích','Gửi số trang','Báo lỗi','Cảm nghĩ','Bài phân tích','Mong có câu này'].map((t,i)=>`<article class="task"><div><span class="type">${t}</span><h3>Góp ý mẫu cho Dòng mẫu một của bài</h3><p>Nội dung tổng hợp. Không thu email, số điện thoại hoặc IP.</p></div>${link('A02','Xem nội dung','btn compact','state='+['contribution','contribution','contribution','report','analysis','analysis','wish'][i])}</article>`).join('')}`;
V.A16=(s)=>`<p class="eyebrow">Số liệu tuần</p><h1>Từ lượt đọc đến việc nên làm.</h1>${s==='empty'?empty('Chưa đủ dữ liệu để tổng hợp','Không tính tăng trưởng từ số 0.'):notice('Tất cả số là dữ liệu thử; không phải số liệu của phongdao.com.')+`<div class="grid">${[['1.258','Lượt đọc'],['12','Trích dẫn sao chép'],['38','Chia sẻ']].map(([n,t])=>`<div class="metric"><span class="num">${n}</span><p>${t}</p></div>`).join('')}</div>${section('Việc nên ưu tiên',`<table class="table responsive"><thead><tr><th>Tín hiệu</th><th>Số mẫu</th><th>Hành động</th></tr></thead><tbody>${[['Tìm không ra','9','Thêm bài','wish'],['Mong có','4','Tạo ứng viên','wish'],['Từ “chút” được chạm','18','Viết nghĩa kỹ hơn','meaning'],['Bài đọc nhiều chưa nghĩa','3','Xem nháp nghĩa','meaning']].map(([t,n,a,s])=>`<tr><td>${t}</td><td>${n}</td><td>${link('A02',a,'','state='+s)}</td></tr>`).join('')}</tbody></table>`)}${section('Theo thể loại & cấp nội bộ','<p>Ca dao: 8 bài · 6 L2. Tục ngữ – Thành ngữ: 8 bài · 4 L2. Cấp chất lượng do dữ liệu tính.</p>')}`}`;
V.A17=(s)=>`<p class="eyebrow">Cài đặt</p><h1>Vừa đủ cho một người biên soạn.</h1>${s==='editor'?notice('Bạn đang thử vai Biên tập. Các thay đổi cài đặt thuộc quyền Quản trị.'):''}<fieldset ${s==='editor'?'disabled':''} style="border:0;padding:0">${input('settings-alias','Bút danh — chỉ hiện Biên soạn khi có')}${input('settings-candidates','Số ứng viên mỗi ngày','10','number')}${select('settings-material','Tên khối tư liệu',['Thông tin tư liệu','Lời này từ đâu?'])}<p>${link('A11','Chính sách nguồn → Hồ sơ nguồn')}</p>${details('Turnstile',input('turnstile-secret','Khoá dịch vụ — chỉ nhập trong WordPress thật','','password')+'<p class="small muted">Không có khoá thật trong nguyên mẫu.</p>')}<label class="choice"><input type="checkbox" id="settings-maintenance">Bảo trì</label><label class="choice"><input type="checkbox" id="settings-second-editor">Người duyệt khác người nhập — chỉ khi có người thứ hai</label><div class="actions">${btn('save-settings','Lưu cài đặt mô phỏng','primary')}</div></fieldset><p id="settings-status" aria-live="polite"></p>`;
V.A18=()=>`<p class="eyebrow">Lịch sử</p><h1>Thay đổi có dấu vết.</h1><label for="history-target">Đối tượng</label><select id="history-target"><option>Tác phẩm mẫu</option><option>Hồ sơ nguồn mẫu</option></select>${section('Nhật ký mẫu',`<article class="card"><div class="row between"><strong>Người biên soạn mẫu</strong><span class="small muted">Thời điểm trong phiên mô phỏng</span></div><p>Lớp nghĩa · Cập nhật nội dung</p><div class="grid two"><div><h3>Trước</h3><p>Nháp tổng hợp chưa duyệt.</p></div><div><h3>Sau</h3><p>Một câu giải nghĩa tổng hợp để xem khối Ý nghĩa.</p></div></div><p class="small muted">Nhật ký để xem lại. Hoàn tác 10 giây nằm ở quyết định vừa thực hiện; không cung cấp khôi phục tuỳ ý mọi phiên bản.</p></article>`)}${link('A04','Về tác phẩm','btn')}`;
V.A19=(s)=>`<p class="eyebrow">Gộp hai tác phẩm đã đăng</p><h1>Chọn bài giữ lại, xem đủ hệ quả.</h1><div class="grid two"><article class="card"><label class="choice"><input type="radio" name="keep-work" value="a" checked>Giữ Dòng mẫu một của bài</label>${verse(poem,'lucbat',false)}<p class="small muted">/ca-dao/mau-a/ · 24 lượt đọc mẫu</p></article><article class="card"><label class="choice"><input type="radio" name="keep-work" value="b">Giữ Bài mẫu khác</label>${verse(['Dòng mẫu khác của bài này','Dòng mẫu hai khác dài hơn cho vừa'],'lucbat',false).replaceAll('khác','<ins>khác</ins>')}<p class="small muted">/ca-dao/mau-b/ · 18 lượt đọc mẫu</p></article></div><section class="section"><h2>Điều sẽ thay đổi</h2><div id="merge-impact"><p>Giữ: <strong>Dòng mẫu một của bài</strong>. Bài mẫu khác trở thành dị bản.</p><p>/ca-dao/mau-b/ chuyển hướng 301 tới /ca-dao/mau-a/.</p></div><ul class="steps"><li>Lượt đọc, cảm nghĩ, bài phân tích và liên kết tuyển tập được dồn sang bài giữ.</li><li>Bài còn lại vào thùng rác, có thể khôi phục.</li><li>Ghi nhật ký người quyết và thay đổi trước / sau.</li></ul></section>${s==='confirmed'?notice('Đã gộp trong phiên mô phỏng; không có bài thật nào thay đổi.','success'):''}<div class="actions">${btn('merge','Xem xác nhận gộp','primary')}${link('A02','Để sau','btn ghost','state=duplicate')}</div><p id="merge-status" aria-live="polite"></p>`;
V.A20=(s)=>`<p class="eyebrow">Sau chuyển dữ liệu</p><h1>Những phần cần xem lại.</h1><p class="muted">Bài đã đăng giữ nguyên trạng thái. Danh sách này không trở thành lỗi trên trang công khai.</p>${s==='empty'?empty('Không còn mục cần xem','Báo cáo chuyển dữ liệu chỉ giữ ID, số lượng và lý do.'):['Chú thích chưa neo chắc chắn','Lời có chỉnh tay cần đối chiếu','Tuyển tập chưa đủ 8 câu'].map((t,i)=>`<article class="task"><div><span class="tag">ID mẫu ${101+i}</span><h3>${t}</h3><p>Trạng thái: đã đăng · cần người xem phần liên quan.</p></div>${link(i===2?'A05':'A04','Mở đúng vùng sửa','btn compact','anchor=editor-'+(i===0?5:1))}</article>`).join('')}${notice('Không có nút chạy nhập dữ liệu hoặc hoàn tác production trong nguyên mẫu. Công cụ vận hành thực tế nằm ngoài phạm vi UX này.')}`;
V.A21=(s)=>`<p class="eyebrow">Quyền & phiên</p><h1>${s==='expired'?'Phiên của bạn đã hết hạn.':s==='denied'?'Bạn chưa có quyền thực hiện việc này.':'Thử từng vai sử dụng.'}</h1><div class="row">${[['admin','Quản trị'],['editor','Biên tập'],['contributor','Cộng tác']].map(([v,t])=>link('A21',t,'chip '+(v===s?'selected':''),'state='+v)).join('')}</div>${notice(s==='contributor'?'Có thể gửi đối chiếu / soát lời khi mở; không có quyền Đăng.':s==='editor'?'Có thể soạn, duyệt và quản lý nội dung. Không đổi giấy phép, xin phép hoặc chính sách nguồn.':s==='expired'?'Giữ phần đang sửa. Bạn có thể sao chép trước khi quay lại luồng đăng nhập WordPress.':'Vai Quản trị quản lý nội dung, nguồn và cài đặt.')}<div class="actions">${link('A04','Mở soạn tác phẩm','btn',s==='expired'?'state=expired':'')}${btn('role-publish','Đăng mô phỏng','primary',['contributor','expired','denied'].includes(s)?'disabled':'')}${link('A11','Xem hồ sơ nguồn','btn',s==='editor'?'state=editor':'')}</div>${section('Thêm — các vùng quản lý',`<div class="grid two">${[['A05','Tuyển tập'],['A06','Từ điển'],['A07','Trò chơi'],['A08','Mô-típ'],['A09','Chủ đề & vùng'],['A10','Thể loại'],['A11','Hồ sơ nguồn'],['A12','Nguồn tự động'],['A13','Kho thu thập'],['A14','Máy đang làm'],['A15','Người đọc gửi'],['A16','Số liệu'],['A17','Cài đặt'],['A18','Lịch sử'],['A20','Cần xem']].map(([r,t])=>link(r,t+icon('arrow'),'btn')).join('')}</div>`)}`;
const phaseNote=()=>notice('Đợt 5 — thiết kế chuẩn bị, chưa bật trên site ra mắt. Dữ liệu tổng hợp dùng để duyệt bố cục và hành vi.');
V.F01=(s)=>`${bread('Cho lớp học','R01','Đợt mở rộng')}<p class="eyebrow">Cho lớp học</p><h1>Chuẩn bị một tiết học.</h1>${phaseNote()}${s==='closed'?empty('Chưa mở trên điều hướng','Cần ít nhất 3 bài học có bộ câu SGK. Bộ ra mắt vẫn dùng chủ đề → lưu 5 câu → trình chiếu.',link('R04','Thử luồng soạn bài ở bản ra mắt','btn primary')):`<div class="field-grid"><div>${select('school-class','Lớp',['Lớp mẫu 6','Lớp mẫu 7','Lớp mẫu 8'])}</div><div>${select('school-book','Bộ sách',['Sách mẫu tổng hợp — dữ liệu thử'])}</div></div><p class="small muted">Lựa chọn nhớ trên máy. Không khẳng định câu có trong SGK thật.</p>${section('Bài học có bộ câu',`<div class="grid">${['Bài học mẫu 1','Bài học mẫu 2','Bài học mẫu 3'].map(t=>`<article class="card"><span class="tag">Đã có hồ sơ SGK tổng hợp</span><h2>${link('F02',t)}</h2><p>8 câu mẫu · nghĩa dùng lại từ tác phẩm</p>${link('F02','Mở bộ câu '+icon('arrow'),'btn primary')}</article>`).join('')}</div>`)}`}<p class="small">Chưa thấy bài cần? ${link('R22','Gửi tên sách, trang '+icon('arrow'),'btn ghost','type=3')}</p>`;
V.F02=(s)=>`${bread('Bài học mẫu 1','F01','Cho lớp học')}<p class="eyebrow">Bộ câu SGK · dữ liệu thử</p><h1>Bài học mẫu 1</h1>${phaseNote()}<p>Hồ sơ SGK mẫu: Sách mẫu tổng hợp · lớp mẫu · trang mẫu. Không dùng để xác nhận một bộ sách thật.</p><div class="actions">${btn('present','Trình chiếu cả bộ','primary','data-set="collection"')}${link('F03','Phiếu in A4','btn')}${btn('cite-set','Sao chép trích dẫn cả bộ')}</div>${s==='missing'?notice('Chưa có đủ tác phẩm của bài học. '+link('R22','Gửi tên sách, trang','','type=3')):''}<div data-collection>${fixtures.slice(0,8).map((p,i)=>collectionItem(p,i+1)).join('')}</div>`;
V.F03=(s)=>`<p class="eyebrow">Phiếu in · Đợt 5</p><h1>Bộ câu cho bài học mẫu</h1><p class="small muted">Thư viện Văn học Dân gian Việt Nam · phongdao.com · dữ liệu thử</p><div class="actions">${btn('print',icon('print')+'In A4','primary')}${link('F02','Về bộ câu','btn ghost')}</div><p class="small no-print">${s==='long'?'Bộ dài cho nhiều trang A4, không ép vào một tờ.':'Một trang mẫu với 2 câu; ngắt trang theo nội dung.'}</p><div class="worksheet">${fixtures.slice(0,s==='long'?30:2).map((p,i)=>`<article class="collection-item"><span class="num">${i+1}</span><div><p class="tag">${p.genre}</p>${verse(p.lines,p.genre==='Ca dao'?'lucbat':'',false)}${p.meaning?'<p><strong>Ý nghĩa:</strong> '+p.meaning+'</p>':''}<p class="small">Chú thích: phần tổng hợp để kiểm giao diện.</p>${level()}<p class="small">Trích dẫn: “${p.title}” (${p.genre}). Thư viện Văn học Dân gian Việt Nam. https://phongdao.com/${['ca-dao','tuc-ngu','dong-dao','cau-do','ve'][i%5]}/mau/</p></div></article>`).join('')}</div>`;
V.F04=(s)=>`${bread('Truyện mẫu','F01','Đợt mở rộng')}<p class="eyebrow">Truyện · thiết kế chuẩn bị</p><h1>Bản kể mẫu theo đoạn</h1>${phaseNote()}<p class="level">Bản kể theo: hồ sơ sách / năm / trang chưa được cung cấp. Chưa có điều kiện công khai.</p>${s==='warning'?notice('Vị trí cảnh báo bối cảnh nhạy cảm, chỉ hiện khi có lưu ý do người biên soạn xác nhận.'):''}<p class="small muted">2 đoạn tổng hợp · tuổi đọc: chưa có dữ liệu</p><div class="actions">${btn('story','Kể cho bé','primary')}${btn('aa','Aa')}${btn('print','In')}</div>${details('Mục lục','<p><a href="#story-1">Đoạn 1</a></p><p><a href="#story-2">Đoạn 2</a></p>')}<section id="story-1" class="section"><h2>Đoạn 1</h2><p>Đoạn mẫu thứ nhất để kiểm bố cục kể theo đoạn. Đây không phải một bản kể dân gian được biên soạn hoặc xác minh.</p></section><section id="story-2" class="section"><h2>Đoạn 2</h2><p>Đoạn mẫu thứ hai để kiểm chữ lớn, mục lục và khả năng chuyển đoạn. Tài sản sách quét và quyền phải được chủ dự án kiểm trước khi có nội dung thật.</p></section>${details('Nhân vật','<p>Hồ sơ nhân vật mẫu, tách khỏi lời kể.</p>')}${details('Chú thích','<p>Chú thích tổng hợp để kiểm bề mặt.</p>')}${details('Ý nghĩa','<p>Phần này do người biên soạn viết và duyệt, không tự diễn giải từ một truyện chưa được cung cấp.</p>')}${details('Bản kể khác','<p>Danh sách bản kể theo từng hồ sơ sách khi có.</p>')}${materials()}${contribute()}`;
V.F05=(s)=>`${bread('Thể loại mở rộng','R01','Đợt 5')}<p class="eyebrow">${s==='ho'?'Hò':s==='ly'?'Lý':'Hát ru'} · mẫu văn bản</p><h1>Lời mẫu cho thể loại mở rộng</h1>${phaseNote()}${s==='closed'?empty('Thể loại chưa qua cổng','Không xuất hiện trên menu bản ra mắt.',link('F09','Xem điều kiện mở','btn')):notice('Chưa có văn bản, hồ sơ nguồn và mẫu riêng được duyệt. Khối lời dưới chỉ dùng fixture chung để thử nhịp chữ.')+verse(poem,'',false)+level()+actions()+details('Thông tin cách trình bày','<p>Chỉ hiện lối hát khi người biên soạn có căn cứ. Không giả video hoặc âm thanh diễn xướng.</p>')}`;
V.F06=(s)=>`${bread('Nghe','R01','Đợt 5')}<p class="eyebrow">Nghe · bề mặt đề xuất</p><h1>Nghe một lời đã được soát.</h1>${phaseNote()}${s==='no-audio'?empty('Bài này chưa có giọng đọc đã duyệt','Không để player rỗng trong trang đọc. Bạn có thể đọc văn bản.',link('R05','Đọc tác phẩm','btn primary')):`<article class="card"><span class="tag">Giọng đọc máy · mô phỏng giao diện</span><h2>Dòng mẫu một của bài</h2><p class="small muted">Chưa có tệp âm thanh được duyệt. Nút dưới chỉ mô phỏng phát / dừng, không phát tiếng.</p><div class="actions">${btn('audio-sim','Phát thử giao diện','primary')}<span id="audio-time" class="small" aria-live="polite">00:00 / 00:30 · thời lượng mẫu</span></div><progress id="audio-progress" value="0" max="30" style="width:100%;accent-color:var(--son)">0 / 30</progress></article><div class="section">${verse()}${level()}</div>`}<p class="small muted">Hub và route Nghe chưa chốt. Production chỉ tải tệp sau khi bấm, dùng giọng sinh sẵn đã qua nghe thử. Giọng máy không thay diễn xướng.</p>`;
V.F07=(s)=>`<p class="eyebrow">Đợt 5 / Đối chiếu sách</p><h1>Đặt lời bên cạnh trang sách.</h1>${phaseNote()}<div class="row"><button class="chip" data-action="scan-tab" data-tab="text">Lời hiện tại</button><button class="chip" data-action="scan-tab" data-tab="scan">Trang quét</button></div><div class="grid two section"><section class="card" id="scan-text"><h2>Lời hiện tại</h2>${verse(poem,'lucbat',false)}${details('Đề xuất máy — chưa xác nhận','<p>Vùng so chữ khác. Chưa có trang quét để tạo đề xuất có căn cứ.</p>')}</section><section class="card" id="scan-image"><h2>Trang quét</h2><div class="empty"><p>Chưa có bản quét được cung cấp.</p><p class="small muted">Không tạo ảnh giả một trang sách. Khi có bản quét đã kiểm quyền, hiển thị tên sách, trang và khả năng phóng to tại đây.</p></div></section></div><div class="field-grid"><div>${input('scan-book','Tên sách / hồ sơ nguồn')}</div><div>${input('scan-page','Số trang')}</div></div><label class="choice"><input id="scan-confirmed" type="checkbox">Tôi đã xem bản quét và xác nhận đối chiếu</label><p class="small muted">Hiện chưa có bản quét nên nút xác nhận bị chặn bởi thiếu bằng chứng, không tự điền tên sách / trang.</p>${btn('scan-confirm','Xác nhận đối chiếu','','disabled')}`;
V.F08=(s)=>`<p class="eyebrow">Đợt 5 / Kiểm giọng</p><h1>Nghe thử trước khi sinh cả kho.</h1>${phaseNote()}<div class="row between"><p><strong id="voice-count">0</strong> / 30 bài mẫu đã đánh giá trong phiên</p>${btn('voice-next','Bài tiếp theo','primary')}</div><div id="voice-card" class="review-card"><span class="tag" id="voice-genre">Ca dao · bài 1 / 30</span><h2>Dòng mẫu một của bài</h2>${verse()}<p class="small muted">Chưa có tệp âm thanh. Các thao tác bên dưới chỉ kiểm quy trình đánh giá.</p>${btn('audio-sim','Phát thử giao diện','compact')}<div class="actions">${btn('voice-pass','Đạt · mô phỏng','primary')}${btn('voice-fail','Sai · ghi lỗi')}</div>${area('voice-error','Lỗi ngắt nhịp / phát âm / thanh điệu',s==='failed'?'Lỗi tổng hợp để thử thao tác ghi nhận.':'')}<label class="choice"><input type="checkbox" id="voice-disabled">Tắt giọng của bài này</label><p id="voice-feedback" aria-live="polite"></p></div>${section('Lô kiểm 30 bài',`<div class="row">${Array.from({length:30},(_,i)=>`<button class="chip" data-action="voice-jump" data-index="${i}">${i+1}</button>`).join('')}</div>`)}`;
V.F09=(s)=>`<p class="eyebrow">Đợt 5 / Cổng thể loại</p><h1>Đủ điều kiện, rồi người quyết.</h1>${phaseNote()}<label for="gate-genre">Thể loại đang chuẩn bị</label><select id="gate-genre"><option>Truyện</option><option>Hát ru</option><option>Hò</option><option>Lý</option></select><section class="section"><table class="table responsive"><thead><tr><th>Điều kiện</th><th>Dữ liệu mẫu</th><th>Trạng thái</th></tr></thead><tbody>${[['Mẫu riêng qua trợ năng',s==='eligible'?'Kết quả mô phỏng: đã có':'Chưa có báo cáo'],['Bài đã đăng ≥ 20',s==='eligible'?'20 / 20':'12 / 20'],['Bài L2 ≥ 10',s==='eligible'?'10 / 10':'6 / 10'],['Hồ sơ nguồn và quyền đã ghi',s==='eligible'?'Đủ hồ sơ mẫu':'Còn thiếu'],['Truyện: sách hết bản quyền có bản quét được chủ dự án kiểm',s==='eligible'?'Bằng chứng tổng hợp để thử trạng thái':'Chưa có hồ sơ']].map(([t,v])=>`<tr><td>${t}</td><td>${v}</td><td><span class="status ${s==='eligible'?'':'pending'}">${s==='eligible'?'Đủ trong mẫu':'Chưa đủ'}</span></td></tr>`).join('')}</tbody></table></section>${notice(s==='eligible'?'Đủ điều kiện mẫu · chờ người quyết. Không tự bật menu.':'Chưa đủ điều kiện → thể loại không xuất hiện trên menu.')}<div class="actions">${btn('open-gate','Quyết định mở mô phỏng','primary',s==='eligible'?'':'disabled aria-describedby="gate-status"')}</div><p id="gate-status" aria-live="polite">Các trạng thái không là bằng chứng đã qua kiểm production.</p>`;
V.F10=(s)=>`${bread('Dữ liệu mở','R01','Đợt 5')}<p class="eyebrow">Dữ liệu mở · bề mặt đề xuất</p><h1>Một bản dữ liệu có thể trích dẫn.</h1>${phaseNote()}<p>Khả năng xuất có phiên bản đã chốt. Trang tải công khai dưới đây là đề xuất thể hiện, cần chủ dự án chọn.</p>${s==='empty'?empty('Chưa có bản dữ liệu để tải','Chỉ xuất tác phẩm đã đăng, lớp đã duyệt và nguồn có quyền.'):section('Bản fixture v0.1',`<div class="card"><h2>Dữ liệu thử cho prototype</h2><p>38 bản ghi tổng hợp · JSON · không phải kho nội dung thật.</p><p>Phạm vi: lời mẫu, tên, thể loại, nghĩa mẫu và cờ. Loại trừ nguồn ẩn, kho thô, nháp, dữ liệu cá nhân.</p>${btn('export-data','Tải JSON fixture','primary')}</div>`)}${section('Thông tin phiên bản','<p>README, nguồn gốc fixture và danh mục tài sản nằm trong gói bàn giao. Mỗi bản production cần phạm vi, giấy phép theo lớp và ngày phát hành thật.</p>')}`;
V.D04=(s)=>{const p=s==='proverb'?fixtures[1]:fixtures[0];return `<p class="eyebrow">Ảnh chia sẻ · ngang 1200 × 630 · vuông 1080 × 1080 · dọc 1080 × 1350</p><h1>Đủ lời, đúng khổ, có nguồn.</h1><p class="muted">Máy chủ tạo ảnh PNG theo khổ và nền người đọc chọn; nền theo thể loại, hoạ tiết vẽ bằng SVG của dự án (trống đồng, mây, sóng, chấm, sao). Lời luôn mỗi câu một dòng, co chữ vừa khung. Câu đố không lộ đáp án. Ảnh mặc định khi dán liên kết là khổ ngang, nền đầu tiên của thể loại.</p>${s==='generic'?`<div class="acs"><figure class="anh-chia-se" data-nen="tim" data-fit-h aria-label="Ảnh chia sẻ chung của thư viện"><svg class="hoa-tiet m-tim" viewBox="0 0 400 400" aria-hidden="true">${'<circle cx="200" cy="200" r="80"/><circle cx="200" cy="200" r="120"/><circle cx="200" cy="200" r="160"/>'}</svg><div class="acs-trong"><span class="acs-the-loai">Thư viện Văn học Dân gian Việt Nam</span>${verse(['Đọc một câu.','Hiểu một đời sống.'],'',false,false,{max:'w0.075'})}<div class="acs-chan"><span class="logo" aria-hidden="true">P</span><span>Mỗi câu ghi rõ lấy từ đâu<small>phongdao.com</small></span></div></div></figure></div>`:shareBlock(s==='flag'?{...fixtures[30],genre:'Ca dao',lines:poem}:p)}${s==='flag'?'<p class="flag">Ảnh của câu có cờ ghi thêm “Nghi không phải dân gian · đọc lý do trước khi chia sẻ” ở chân ảnh.</p>':''}<p class="small muted">Các câu trên là dữ liệu thử.</p>`;};
const mapMarkup=()=>{const file=new URL('../assets/ban-do-vn.svg',import.meta.url);if(!fs.existsSync(file))return '';return `<figure style="margin:0"><img src="data:image/svg+xml;base64,${fs.readFileSync(file).toString('base64')}" width="460" height="460" style="width:100%;height:auto;max-width:460px" alt="Bản đồ Việt Nam từ tài sản dự án, có Hoàng Sa và Trường Sa"><figcaption class="small muted">Tài sản ban-do-vn.svg từ repo ở commit đã ghim. Danh sách địa danh bên cạnh là fixture; không thêm pin giả lên bản đồ.</figcaption></figure>`;};
const oldMap=V.R15;V.R15=s=>s==='missing'?oldMap(s):oldMap(s).replace('<div class="map-area"><h2>Bản đồ đang chờ tài sản phù hợp</h2><p class="muted">Bản xem này giữ danh sách địa danh để tra cứu. Cần dùng SVG đúng của dự án, có Hoàng Sa và Trường Sa.</p><p class="small">Không tự vẽ lại địa giới để lấp chỗ trống.</p></div>',`<div class="map-area" style="padding:20px">${mapMarkup()}</div>`);
